def p2(k):
    return f"{S[k]['irr']*100:.2f}%"


def m1(v):
    return f"£{v/1e6:.1f}m"


def m2(v):
    return f"£{v/1e6:.2f}m"


def case(k, field, fmt=m1):
    return fmt(CASE[k][field])


def rung(p, lever):
    r = RUNG[p][lever]["solved"]
    return {"adr": f"£{r:,.0f}", "exit_yield": f"{r*100:.2f}%", "resi_psf": f"£{r:,.0f}"}[lever]


def neg(v):
    """A negative percentage as the page prints it."""
    return f"({abs(v)*100:.2f})%" if v < 0 else f"{v*100:.2f}%"


