# ══ splice ════════════════════════════════════════════════════════════
def chapter_span(s, cid):
    """The whole chapter object, from its opening brace to the next one."""
    i = s.index(f'  id: "{cid}", num: "')
    start = s.rindex("{", 0, i)
    nxt = s.find('  id: "', i + 10)
    while nxt != -1 and s[nxt:nxt + 40].split('"')[1] in ("", cid):
        nxt = s.find('  id: "', nxt + 10)
    end = s.rindex("{", 0, nxt) if nxt != -1 else s.index("\n];", i)
    return start, end


def main():
    s = open(IDX, encoding="utf-8").read()
    before = len(s)

    for cid, text in (("summary", CH01), ("underwrite", ch04()), ("returns", ch06()),
                      ("bridge", ch07())):
        a, b = chapter_span(s, cid)
        s = s[:a] + text + "\n" + s[b:]
        print(f"  chapter {cid} rewritten")

    for old, new, want in replacements():
        n = s.count(old)
        assert n and (want is None or n == want), f"{n} hits for: {old[:70]}"
        s = s.replace(old, new)
        print(f"  x{n}  {old[:58]}")

    # the case plates read the underwrite against each comparable
    ca, cb = s.index("const CASES = ["), s.index("const CHEAT = {")
    seg = s[ca:cb]
    for old, new in (("33.96%", F["gop_margin_y7"]), ("£45.33m", F["rev_y7"]),
                     ("£123.6m", F["capex_hotel"]), ("£2.06m", F["capex_hotel_per_key"]),
                     ("£15.39m", F["gop_y7"])):
        n = seg.count(old)
        if n:
            seg = seg.replace(old, new)
            print(f"  cases x{n}  {old}")
    s = s[:ca] + seg + s[cb:]

    open(IDX, "w", encoding="utf-8", newline="").write(s)
    print(f"rewrote {IDX}  ({before:,} -> {len(s):,} bytes)")


if __name__ == "__main__":
    main()
